SELECT 
FROM recurring_investment_plan
WHERE plan_id = #{planId}
  AND user_id = #{userId}

SELECT EXISTS(
    SELECT 1
    FROM connected_account account
    INNER JOIN codef_connection connection
        ON connection.connection_id = account.connection_id
    WHERE account.account_id = #{accountId}
      AND connection.user_id = #{userId}
      AND account.business_type = 'ST'
      AND account.status = 'ACTIVE'
)
